// Psycho-Nics Oscar - initial video timing bring-up
// 48 MHz FPGA clock; 6 MHz pixel enable (one pulse per eight clocks).
// Video timing generated by jtframe_vtimer.
//
// Target timing:
//   Pixel clock:  6.000 MHz
//   Horizontal:   384 pixels, 15.625 kHz
//   Vertical:     272 lines, 57.445 Hz
//   Visible:      256 x 240
//
// HS/VS positions remain provisional until verified against
// the DE-0301 schematics.
//
// LHBL/LVBL are ACTIVE HIGH during the visible area.

module jtoscar_video (
    input  wire       clk,
    input  wire       rst,
    output wire       pxl_cen,
    output wire       HS,
    output wire       VS,
    output wire       LHBL,
    output wire       LVBL,
    output reg  [3:0] red,
    output reg  [3:0] green,
    output reg  [3:0] blue
);

    // ------------------------------------------------------------
    // Pixel clock enable: 48 MHz / 8 = 6 MHz
    // ------------------------------------------------------------

    reg [2:0] div8;
    reg pixel_ce_reg;

    assign pxl_cen = pixel_ce_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            div8         <= 3'd0;
            pixel_ce_reg <= 1'b0;
        end else begin
            div8         <= div8 + 3'd1;
            pixel_ce_reg <= (div8 == 3'd7);
        end
    end

    // ------------------------------------------------------------
    // JTFRAME video timer
    // ------------------------------------------------------------

    wire [8:0] hdump;
    wire [8:0] vdump;

    jtframe_vtimer #(
        .VB_START   ( 9'd248 ),
        .VB_END     ( 9'd8   ),
        .VCNT_END   ( 9'd271 ),
        .VS_START   ( 9'd256 ),
    
        .HS_START   ( 9'd432 ),
        .HB_START   ( 9'd384 ),
        .HJUMP      ( 1      ),
        .HB_END     ( 9'd0   ),
        .HINIT      ( 9'd128 )
    ) u_vtimer (
        .clk        ( clk     ),
        .pxl_cen    ( pxl_cen ),
        .vdump      ( vdump   ),
        .vrender    (         ),
        .vrender1   (         ),
        .H          ( hdump   ),
        .Hinit      (         ),
        .Vinit      (         ),
        .LHBL       ( LHBL    ),
        .LVBL       ( LVBL    ),
        .HS         ( HS      ),
        .VS         ( VS      )
    );

    // ------------------------------------------------------------
    // Eight vertical colour bars
    // ------------------------------------------------------------

    wire [8:0] hpos = hdump;
    
    always @* begin
        red   = 4'h0;
        green = 4'h0;
        blue  = 4'h0;
    
        if (LHBL && LVBL) begin
            red   = 4'hf;
            green = 4'hf;
            blue  = 4'hf;
        end
    end

   /* always @* begin
        red   = 4'h0;
        green = 4'h0;
        blue  = 4'h0;

        if (LHBL && LVBL) begin
            case (hpos[7:5])
                3'd0: begin red=4'hf; green=4'hf; blue=4'hf; end // White
                3'd1: begin red=4'hf; green=4'hf; end           // Yellow
                3'd2: begin green=4'hf; blue=4'hf; end         // Cyan
                3'd3: begin green=4'hf; end                    // Green
                3'd4: begin red=4'hf; blue=4'hf; end           // Magenta
                3'd5: begin red=4'hf; end                      // Red
                3'd6: begin blue=4'hf; end                     // Blue
                default: begin end                             // Black
            endcase
        end
    end*/
    
    

endmodule